#include <bits/stdc++.h>
using namespace std;

struct DepthTree {
    int n;
    vector<int> mn, lazy;

    DepthTree(const vector<int>& a) {
        n = (int)a.size();
        mn.resize(4 * n);
        lazy.assign(4 * n, -1);
        build(1, 0, n - 1, a);
    }

    void build(int node, int l, int r, const vector<int>& a) {
        if (l == r) {
            mn[node] = a[l];
            return;
        }
        int mid = (l + r) / 2;
        build(node * 2, l, mid, a);
        build(node * 2 + 1, mid + 1, r, a);
        mn[node] = min(mn[node * 2], mn[node * 2 + 1]);
    }

    void apply(int node, int value) {
        mn[node] = value;
        lazy[node] = value;
    }

    void push(int node) {
        if (lazy[node] != -1) {
            apply(node * 2, lazy[node]);
            apply(node * 2 + 1, lazy[node]);
            lazy[node] = -1;
        }
    }

    void assignRange(int node, int l, int r, int ql, int qr, int value) {
        if (ql <= l && r <= qr) {
            apply(node, value);
            return;
        }
        push(node);
        int mid = (l + r) / 2;
        if (ql <= mid) assignRange(node * 2, l, mid, ql, qr, value);
        if (qr > mid) assignRange(node * 2 + 1, mid + 1, r, ql, qr, value);
        mn[node] = min(mn[node * 2], mn[node * 2 + 1]);
    }

    void assignRange(int l, int r, int value) {
        if (l <= r) assignRange(1, 0, n - 1, l, r, value);
    }

    int point(int node, int l, int r, int pos) {
        if (l == r) return mn[node];
        push(node);
        int mid = (l + r) / 2;
        if (pos <= mid) return point(node * 2, l, mid, pos);
        return point(node * 2 + 1, mid + 1, r, pos);
    }

    int point(int pos) {
        return point(1, 0, n - 1, pos);
    }

    int rightmostAtMost(int node, int l, int r, int qr, int value) {
        if (l > qr || mn[node] > value) return -1;
        if (l == r) return l;
        push(node);
        int mid = (l + r) / 2;
        int result = rightmostAtMost(node * 2 + 1, mid + 1, r, qr, value);
        if (result != -1) return result;
        return rightmostAtMost(node * 2, l, mid, qr, value);
    }

    int rightmostAtMost(int qr, int value) {
        return rightmostAtMost(1, 0, n - 1, qr, value);
    }
};

